import {PicoROMRuntime} from './pico-rom-runtime.js';
import {loadPicoROM} from './pico-rom-assets.js';
import {loadNativePicoFirmware,PICO_NATIVE_FIRMWARE} from './pico-native-firmware.js';
import {installNativeCorePower} from './pico-native-power.js';
import {installGPIOCoprocessor} from './pico-gpio-coproc.js';
import {PicoCircuit,PicoRuntime,solvePicoCircuit} from './pico-runtime.js';
import {validateProject,componentDefinition} from './core.js';
import {emptyProject} from './templates.js';
import {defaultPicoEnvironment,picoEnvironment,sampleInternalADC} from './pico-environment.js';
import {installPicoADC} from './pico-adc-fix.js';
import {installPicoDMA} from './pico-dma-fix.js';
export async function loadNativePicoPython(id,project,source,files=[]){const chip=id.startsWith('pico-2')?'RP2350':'RP2040';const[rom,firmware]=await Promise.all([loadPicoROM(chip),loadNativePicoFirmware(chip)]);return new NativePicoPython(id,rom,firmware,project,source,files);}
// Executes the upstream RP2 interpreter and its _thread implementation as ARM
// machine code on both emulated cores. Python objects/locks share native SRAM.
export class NativePicoPython extends PicoROMRuntime{
 constructor(id,rom,firmware,project,source,files=[]){super(id,rom);this.nativePython=true;this.pico=true;this.native=this;this.chip=id;this.hz=this.board.hz;this.architecture='arm';this.image=firmware;this.rp.flash.set(firmware);this.environment=defaultPicoEnvironment();this.configureEnvironment(project.settings?.picoEnvironment||{});this.power=installNativeCorePower(this.rp);this.coprocessor=installGPIOCoprocessor(this.rp);this.gpioVersion=0;this.inputs={};this.count=0;this.referenceCycles=0;this.serial='';this.transcript='';this.stage='boot';this.program=source;this.files=files;this.circuitDefinition=this.board;this.circuitValidate=p=>validateProject({...emptyProject(),...p,settings:{...(p.settings||{}),picoBuildEngine:undefined,picoSDKTarget:undefined},code:'',files:[],language:'micropython',firmware:undefined});this.circuitSolve=p=>solvePicoCircuit(p);this.partDefinition=componentDefinition;this.emulator={cycles:()=>this.count};
 const read=this.rp.readUint32.bind(this.rp);this.rp.readUint32=a=>a===0xd0000008?(this.newer?0x08000000:2):read(a);for(const g of this.rp.gpio)if(this.board.gpio.includes(g.index))g.addListener(()=>{this.gpioVersion++;this.circuit?.refresh();});this.circuit=new PicoCircuit(this,project);this.circuit.refresh(true);this.usbHost.onSerialData=data=>{const s=new TextDecoder().decode(data);this.transcript=(this.transcript+s).slice(-200000);this.serial=(this.serial+s.replace(/\x04/g,'')).slice(-40000);};this.rp.uart.forEach(u=>u.onByte=b=>{this.serial+=String.fromCharCode(b);});installPicoADC(this);installPicoDMA(this);this.lastADCError=null;this.adcErrorAlarm=this.rp.clock.createAlarm(()=>this.rp.adc.completeADCRead(0,true));const sample=this.rp.adc.onADCRead;this.rp.adc.onADCRead=channel=>{if(!sampleInternalADC(this,channel))return;if(channel<3){this.circuit.refresh(true);const voltage=this.circuit.solution.voltages.get(this.circuit.solution.netlist.net(this.circuit.board.id+':GPIO'+(26+channel)));this.rp.adc.channelValues[channel]=Math.round(Math.max(0,Math.min(3.3,Number.isFinite(voltage)?voltage:0))/3.3*4095);}sample(channel);};}
 configureEnvironment(config){this.environment=picoEnvironment(config);}
 pinStates(){return PicoRuntime.prototype.pinStates.call(this);}
 queueSerial(text){for(const byte of new TextEncoder().encode(text))this.usbHost.sendSerialByte(byte);}
 upload(){const lines=['import os'];const dirs=new Set();for(const f of this.files){if(f.name==='_wirevo_app.py'||!/^([A-Za-z_][\w-]*\/)*[A-Za-z_][\w.-]*\.py$/.test(f.name))throw Error('Native RP2 ek dosya adı geçersiz.');let dir='';for(const part of f.name.split('/').slice(0,-1)){dir+=part+'/';if(!dirs.has(dir)){dirs.add(dir);lines.push('try: os.mkdir('+JSON.stringify(dir)+')\nexcept OSError: pass');}}lines.push('with open('+JSON.stringify(f.name)+',"w") as _f:\n _f.write('+JSON.stringify(f.content)+')');}lines.push('with open("_wirevo_app.py","w") as _f:\n _f.write('+JSON.stringify('__name__="__main__"\n'+this.program)+')','import _wirevo_app');const code=lines.join('\n')+'\n';if(new TextEncoder().encode(code).length>180000)throw Error('Native RP2 yükleme metni çok büyük.');this.queueSerial(code+'\x04');this.stage='running';}
 step(count){for(let i=0;i<count;i++){const before=this.core.cycles;this.rp.currentCore=0;this.core.executeInstruction();this.rp.currentCore=1;let cap=0;while(!this.power.held(1)&&this.rp.core[1].cycles<this.core.cycles&&cap++<64)this.rp.core[1].executeInstruction();this.rp.currentCore=0;this.rp.stepThings(this.core.cycles-before);this.count=this.core.cycles;this.referenceCycles=this.rp.clock.nanos*.016;if(this.circuit.clockEvents[0]?.at<=this.referenceCycles)this.circuit.refresh(true);}if(this.stage==='boot'&&this.usbHost.initialized&&this.usbHost.kind==='cdc'){this.queueSerial('\x03\x01');this.stage='raw';}if(this.stage==='raw'&&this.transcript.includes('raw REPL; CTRL-B to exit\r\n>'))this.upload();if(this.stage!=='running'&&this.core.cycles>100000000)throw Error('Native RP2 USB açılışı süre sınırını aştı.');this.gpioVersion++;this.circuit.refresh(true);const out=this.serial;this.serial='';return out;}
 picoSnapshot(){return{execution:'micropython-rp2-native',architecture:'arm',profile:PICO_NATIVE_FIRMWARE[this.board.mcu].board,version:'1.29.0',stage:this.stage,onboardLED:!this.board.wireless&&this.rp.gpio[25].value===1,core1Running:this.rp.core[1].PC>=0x10000000,cores:this.rp.core.map((c,id)=>({id,running:!this.power.held(id),cycles:c.cycles,pc:c.PC})),usb:this.usbHost.snapshot(),radio:{available:false,link:0,chip:null,model:'Generic RP2 CPU firmware; CYW43 is not initialized'},environment:{...this.environment},adc:{lastError:this.lastADCError},coprocessor:{...this.coprocessor},powerResets:[...this.power.resets]};}
 dispose(){this.circuit?.peripherals?.dispose();this.circuit=null;}
}
